# issue: 525
# Full-formula verification: tied-time correction uses full a = d + (1-q) rest, not d alone.
# Uses only public cmprsk::cuminc() Tests statistics. No cmprsk source or internal routines are read.
variance_stat <- function(ftime,fstatus,group,cause,rho) {
  groups<-sort(unique(group)); K<-length(groups)
  S<-rep(1,K); Fk<-rep(0,K); G0<-1; z<-rep(0,K-1)
  times<-sort(unique(ftime[fstatus!=0])); saved<-vector("list",length(times))
  for(j in seq_along(times)) {
    tt<-times[j]
    Y<-vapply(groups,function(g)sum(group==g&ftime>=tt),0)
    N1<-vapply(groups,function(g)sum(group==g&ftime==tt&fstatus==cause),0)
    N2<-vapply(groups,function(g)sum(group==g&ftime==tt&fstatus!=0&fstatus!=cause),0)
    Sminus<-S; h<-ifelse(Y>0,Y/Sminus,0); R<-ifelse(Y>0,Y*(1-Fk)/Sminus,0)
    d1<-sum(N1); H<-sum(h); RR<-sum(R); L<-G0^rho
    if(d1>0&&RR>0) z<-z+L*(N1[1:(K-1)]-R[1:(K-1)]*d1/RR)
    dF0<-if(H>0)d1/H else 0; Gafter<-G0-dF0
    Safter<-ifelse(Y>0,Sminus*(1-(N1+N2)/Y),0)
    q<-ifelse(Safter>0,Gafter/Safter,0)
    dF2<-ifelse(Y>0,Sminus*N2/Y,0)
    dGamma<-if(G0>0)dF0/G0 else 0
    p<-if(H>0)h/H else rep(0,K)
    D<-matrix(0,K-1,K)
    for(k in 1:(K-1)) D[k,]<-L*h[k]*((1:K==k)-p)
    saved[[j]]<-list(h=h,Y=Y,D=D,dF0=dF0,dF2=dF2,q=q,dGamma=dGamma,
                     L=L,p=p,H=H,d1=d1)
    Fk<-Fk+ifelse(Y>0,Sminus*N1/Y,0); S<-Safter; G0<-Gafter
  }
  m<-length(saved); future<-matrix(0,K-1,K); Sigma<-matrix(0,K-1,K-1)
  if(m>0) for(j in m:1) {
    cur<-saved[[j]]; rest<-future
    aa<-cur$D+sweep(rest,2,1-cur$q,"*")
    bb<--sweep(rest,2,cur$q,"*")
    for(r in 1:K) if(cur$h[r]>0) {
      Sigma<-Sigma+tcrossprod(aa[,r])*cur$dF0/cur$h[r]+
        tcrossprod(bb[,r])*cur$dF2[r]/cur$h[r]
    }
    if(cur$d1>1 && sum(cur$Y)>1 && cur$H>0) {
      W<-matrix(0,K-1,K)
      for(r in 1:K) if(cur$L*cur$h[r]>0) W[,r]<-aa[,r]/(cur$L*cur$h[r])
      qsub<-ifelse(cur$Y>0,cur$h/cur$Y,0)
      Bweights<-ifelse(cur$H>qsub,cur$Y*qsub^2/(cur$H-qsub),0)
      Aown<-W%*%diag(cur$p)%*%t(W)
      Bown<-(sum(cur$Y)-1)/cur$H*(W%*%diag(Bweights)%*%t(W))
      Sigma<-Sigma-cur$L^2*cur$d1*(cur$d1-1)/(sum(cur$Y)-1)*Bown
    }
    future<-future+cur$D*cur$dGamma
  }
  list(z=z,Sigma=Sigma,det=det(Sigma),pred=if(abs(det(Sigma))>1e-12)as.numeric(t(z)%*%solve(Sigma,z)) else NA_real_)
}
run_case <- function(label,ftime,fstatus,group,rho,causes,expected) {
  group<-factor(group,levels=sort(unique(group)))
  fit<-cmprsk::cuminc(ftime,fstatus,group,rho=rho)
  for(i in seq_along(causes)) {
    cause<-as.numeric(causes[i]); actual<-unname(fit$Tests[as.character(cause),"stat"])
    cc<-variance_stat(ftime,fstatus,as.character(group),cause,rho)
    resid<-if(is.finite(cc$pred)&&actual>=0)actual-cc$pred else NA_real_
    cat(label," cause=",cause," rho=",rho," Rstat=",sprintf("%.17g",actual),
        " pred=",sprintf("%.17g",cc$pred)," expected=",sprintf("%.17g",as.numeric(expected[i])),
        " resid=",sprintf("%.17g",resid)," det=",sprintf("%.17g",cc$det),"\n",sep="")
  }
}
